contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public {
        // At this point, c is fresh (never initialized).
        bool revertedFirst;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedFirst = true;
        } else {
            revertedFirst = false;
        }

        bool revertedInit;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedInit = true;
        } else {
            revertedInit = false;
        }

        bool revertedSecond;
        c.SetMinSum(_val); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            revertedSecond = true;
        } else {
            revertedSecond = false;
        }

        assert(revertedFirst == false && revertedInit == false && revertedSecond == true);
    }
}

