pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val) internal {
        bool revertedFirst;
        try c.SetMinSum(_val) {
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }
        bool revertedInit;
        try c.Initialized() {
            revertedInit = false;
        } catch {
            revertedInit = true;
        }
        bool revertedSecond;
        try c.SetMinSum(_val) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }
        assertTrue(revertedFirst == false && revertedInit == false && revertedSecond == true);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
